namespace optiling {
const uint32_t MAX_BLOCK_DIM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    auto xShape = context->GetInputShape(0)->GetOriginShape();
    auto wShape = context->GetInputShape(1)->GetOriginShape();

    uint32_t n   = static_cast<uint32_t>(GetDim(xShape, 0));
    uint32_t cin = static_cast<uint32_t>(GetDim(xShape, 1));
    uint32_t inD = static_cast<uint32_t>(GetDim(xShape, 2));
    uint32_t inH = static_cast<uint32_t>(GetDim(xShape, 3));
    uint32_t inW = static_cast<uint32_t>(GetDim(xShape, 4));

    uint32_t cout = static_cast<uint32_t>(GetDim(wShape, 0));
    uint32_t kD   = static_cast<uint32_t>(GetDim(wShape, 2));
    uint32_t kH   = static_cast<uint32_t>(GetDim(wShape, 3));
    uint32_t kW   = static_cast<uint32_t>(GetDim(wShape, 4));

    // assume stride=(1,1,1), padding=(0,0,0), dilation=(1,1,1)
    uint32_t outD = inD >= kD ? (inD - kD + 1) : 0;
    uint32_t outH = inH >= kH ? (inH - kH + 1) : 0;
    uint32_t outW = inW >= kW ? (inW - kW + 1) : 0;

    ConvStandard3dAsymmetricInputAsymmetricKernelCustomTilingData tiling;
    tiling.set_n(n);
    tiling.set_cin(cin);
    tiling.set_cout(cout);
    tiling.set_inD(inD);
    tiling.set_inH(inH);
    tiling.set_inW(inW);
    tiling.set_kD(kD);
    tiling.set_kH(kH);
    tiling.set_kW(kW);
    tiling.set_outD(outD);
    tiling.set_outH(outH);
    tiling.set_outW(outW);

    uint32_t blockDim = std::min<uint32_t>(MAX_BLOCK_DIM, std::max<uint32_t>(1, cout));
    context->SetBlockDim(blockDim);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *workspaceSizes = context->GetWorkspaceSizes(1);
    workspaceSizes[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

