#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

at::Tensor conv_standard_3d_asymmetric_input_asymmetric_kernel_custom_impl_npu(const at::Tensor& x, const at::Tensor& weight) {
    TORCH_CHECK(x.scalar_type() == at::kFloat, "Only float32 is supported");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "Only float32 weights are supported");
    TORCH_CHECK(x.dim() == 5, "Input x must be 5D (N, C, D, H, W)");
    TORCH_CHECK(weight.dim() == 5, "Weight must be 5D (Cout, Cin, kD, kH, kW)");
    int64_t N   = x.size(0);
    int64_t Cin = x.size(1);
    int64_t inD = x.size(2);
    int64_t inH = x.size(3);
    int64_t inW = x.size(4);

    int64_t Cout = weight.size(0);
    int64_t kD   = weight.size(2);
    int64_t kH   = weight.size(3);
    int64_t kW   = weight.size(4);

    TORCH_CHECK(Cin == weight.size(1), "Input channels mismatch with weight");
    int64_t outD = inD - kD + 1;
    int64_t outH = inH - kH + 1;
    int64_t outW = inW - kW + 1;
    TORCH_CHECK(outD > 0 && outH > 0 && outW > 0, "Invalid output size; check kernel vs input size");

    at::Tensor result = at::empty({N, Cout, outD, outH, outW}, x.options());
    EXEC_NPU_CMD(aclnnConvStandard3dAsymmetricInputAsymmetricKernelCustom, x, weight, result);
    return result;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("conv_standard_3d_asymmetric_input_asymmetric_kernel_custom", &conv_standard_3d_asymmetric_input_asymmetric_kernel_custom_impl_npu);
}

