import torch
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), dilation: tuple = (1, 1, 1), groups: int = 1, bias: bool = False) -> None:
        super().__init__()
        assert stride == (1, 1, 1), "This custom kernel currently supports stride=(1,1,1)"
        assert padding == (0, 0, 0), "This custom kernel currently supports padding=(0,0,0)"
        assert dilation == (1, 1, 1), "This custom kernel currently supports dilation=(1,1,1)"
        assert groups == 1, "This custom kernel currently supports groups=1"
        assert not bias, "This custom kernel currently does not support bias"
        kD, kH, kW = kernel_size
        self.weight = torch.nn.Parameter(torch.empty(out_channels, in_channels, kD, kH, kW))
        # Initialize like nn.Conv3d default (Kaiming uniform)
        torch.nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        # bias is not supported in this custom kernel

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return custom_ops_lib.conv_standard_3d_asymmetric_input_asymmetric_kernel_custom(x, self.weight)
